fn selected(g: &ModelGraph, path: &[serde_json::Value]) -> Atom {
    let mut a = g.root.clone();
    for key in path {
        let id = reference(&a);
        a = if let Node::Map { .. } = &g.nodes[id as usize] {
            mapped(g, id, key.as_str().unwrap())
        } else {
            field(
                g,
                id,
                &key.as_str()
                    .map(str::to_owned)
                    .unwrap_or_else(|| key.as_u64().unwrap().to_string()),
            )
            .clone()
        };
    }
    a
}
fn argument(g: &mut ModelGraph, v: &serde_json::Value) -> Atom {
    use serde_json::Value as J;
    match v {
        J::Null => Atom::Null,
        J::Bool(b) => Atom::Bool(*b),
        J::Number(n) => Atom::Number(n.as_f64().unwrap()),
        J::String(s) => string(g, s),
        J::Array(values) => {
            let atoms = values.iter().map(|v| argument(g, v)).collect();
            Atom::Ref(push_array(g, atoms))
        }
        J::Object(fields) => {
            if let Some(units) = fields.get("$utf16") {
                let id = g.strings.len() as u32;
                g.strings.push(JsString(
                    units
                        .as_array()
                        .unwrap()
                        .iter()
                        .map(|n| n.as_u64().unwrap() as u16)
                        .collect(),
                ));
                return Atom::String(id);
            }
            if let Some(p) = fields.get("$node") {
                return selected(g, p.as_array().unwrap());
            }
            if let Some(n) = fields.get("$number") {
                return Atom::Number(f64::from_bits(
                    u64::from_str_radix(n.as_str().unwrap(), 16).unwrap(),
                ));
            }
            let id = push_object(g, vec![]);
            for (k, v) in fields {
                let a = argument(g, v);
                property(g, id, k, a)
            }
            Atom::Ref(id)
        }
    }
}
fn project(g: &ModelGraph, a: &Atom, sets: bool) -> serde_json::Value {
    use serde_json::{json, Value as J};
    match a {
        Atom::Null | Atom::Undefined => J::Null,
        Atom::Bool(v) => json!(v),
        Atom::String(id) => g.strings[*id as usize]
            .well_formed()
            .map_or_else(|| json!({"$utf16":g.strings[*id as usize].0}), J::String),
        Atom::Number(n) => {
            if !n.is_finite() || n.to_bits() == 0x8000_0000_0000_0000 {
                json!({"$number":format!("{:016x}",n.to_bits())})
            } else if n.fract() == 0. && *n >= 0. && *n < 18446744073709551616. {
                json!(*n as u64)
            } else if n.fract() == 0. && *n >= -9223372036854775808. && *n < 9223372036854775808. {
                json!(*n as i64)
            } else {
                json!(n)
            }
        }
        Atom::Ref(id) => match &g.nodes[*id as usize] {
            Node::Map { entries, .. } => entries
                .iter()
                .map(|(k, v)| json!([project(g, k, sets), project(g, v, sets)]))
                .collect(),
            Node::Set { values, .. } if sets => {
                values.iter().map(|v| project(g, v, sets)).collect()
            }
            Node::Set { .. } => json!({}),
            Node::Array { .. } => array(g, *id).iter().map(|v| project(g, v, sets)).collect(),
            node => {
                let mut out = serde_json::Map::new();
                for p in node.properties() {
                    if !matches!(p.value, Atom::Undefined) {
                        out.insert(
                            g.strings[p.key as usize].well_formed().unwrap(),
                            project(g, &p.value, sets),
                        );
                    }
                }
                J::Object(out)
            }
        },
        _ => panic!("source/method oracle projects data records only"),
    }
}
#[test]
fn all_pinned_native_class_and_member_method_model_svg_vectors() {
    let oracle: serde_json::Value = serde_json::from_str(ORACLE).unwrap();
    let mut count = 0;
    for vector in oracle["vectors"].as_array().unwrap() {
        let mut doc = parsed(vector["source"].as_str().unwrap());
        let options: RenderOptions = serde_json::from_value(
            vector
                .get("options")
                .cloned()
                .unwrap_or_else(|| serde_json::json!({})),
        )
        .unwrap();
        for (call, expected) in vector["calls"]
            .as_array()
            .unwrap()
            .iter()
            .zip(vector["steps"].as_array().unwrap())
        {
            let mut g = doc.snapshot().unwrap();
            if let Some(edit) = call.get("edit") {
                let target = argument(&mut g, &edit["target"]);
                let value = argument(&mut g, &edit["value"]);
                property(
                    &mut g,
                    reference(&target),
                    edit["key"].as_str().unwrap(),
                    value,
                );
            }
            let args = call["args"]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| argument(&mut g, v))
                .collect::<Vec<_>>();
            let receiver = if let Some(value) = call.get("receiver") {
                argument(&mut g, value)
            } else {
                g.root.clone()
            };
            doc.apply(doc.revision(), g).unwrap();
            let id = doc
                .model_schema()
                .methods
                .iter()
                .find(|m| m.name == call["method"].as_str().unwrap())
                .unwrap()
                .id;
            let out = doc
                .invoke(
                    doc.revision(),
                    MethodCall {
                        method: id,
                        receiver,
                        arguments: args.clone(),
                    },
                    &mut MetricsResources,
                )
                .unwrap();
            let actual = match out.result {
                Ok(Atom::Undefined) => serde_json::json!({"kind":"undefined"}),
                Ok(a) => serde_json::json!({"kind":"value","value":project(&out.graph,&a,true)}),
                Err(PublicError::JavaScript { name, message }) => {
                    serde_json::json!({"kind":"error","name":format!("{name:?}"),"message":message.well_formed().unwrap()})
                }
                Err(e) => panic!("{} {}: unexpected {e:?}", vector["name"], call["method"]),
            };
            assert_eq!(
                actual, expected["result"],
                "{} {} return",
                vector["name"], call["method"]
            );
            assert_eq!(
                serde_json::Value::Array(
                    args.iter().map(|a| project(&out.graph, a, true)).collect()
                ),
                expected["argsAfter"],
                "{} {} caller arguments",
                vector["name"],
                call["method"]
            );
            assert_eq!(
                project(&out.graph, &out.graph.root, true),
                expected["model"],
                "{} {} complete model",
                vector["name"],
                call["method"]
            );
            if vector.get("renderGap").is_some() {
                let error = doc.render(&options, &mut MetricsResources).unwrap_err();
                assert!(error.message.contains("lone UTF-16"));
                assert!(expected["rendering"].get("gap").is_some());
                count += 1;
                continue;
            }
            let rendered = doc.render(&options, &mut MetricsResources).unwrap();
            let mut result = serde_json::to_value(rendered).unwrap();
            let svg = result.as_object_mut().unwrap().remove("svg").unwrap();
            result["svgSha256"] =
                format!("{:x}", Sha256::digest(svg.as_str().unwrap().as_bytes())).into();
            assert_eq!(
                result, expected["rendering"],
                "{} {} full SVG",
                vector["name"], call["method"]
            );
            count += 1;
        }
    }
    assert_eq!(count, 114);
    let schema = Class.model_schema();
    for (key, proto) in [
        ("rootMethods", &schema.prototypes[0]),
        ("memberMethods", &schema.prototypes[1]),
    ] {
        let actual = proto
            .members
            .iter()
            .map(|m| {
                let pele::compat::public::MemberKind::Method { method } = m.member else {
                    panic!()
                };
                let method = schema.methods.iter().find(|x| x.id == method).unwrap();
                serde_json::json!({"name":m.name,"arity":method.arity,"flags":m.flags})
            })
            .collect::<Vec<_>>();
        let expected = oracle[key]
            .as_array()
            .unwrap()
            .iter()
            .filter(|m| m["name"] != "constructor")
            .cloned()
            .collect::<Vec<_>>();
        assert_eq!(actual, expected);
    }
}
#[test]
fn class_source_aliases_namespaces_private_tags_and_own_order() {
    let source="classDiagram\nnamespace A.B {\nclass C {\n+x int\n+f(a) bool*\n}\nnote for C \"Note\"\n}\nclassDef hot fill:red\nclass C:::hot\nclick C call x() \"Tip\"\nlink C \"javascript:bad\" _self";
    let mut doc = parsed(source);
    let mut g = doc.snapshot().unwrap();
    let r = root(&g);
    let c = class(&g, "C");
    assert_eq!(
        keys(&g, r),
        [
            "type",
            "lineType",
            "relationType",
            "direction",
            "classes",
            "relations",
            "notes",
            "namespaces",
            "interfaces",
            "styleClasses",
            "title",
            "accTitle",
            "accDescr",
            "namespaceStack",
            "withCssClass"
        ]
    );
    assert!(g.nodes[r as usize]
        .properties()
        .iter()
        .all(|p| p.flags == 7));
    assert!(matches!(field(&g, r, "title"), Atom::Undefined));
    assert_eq!(
        keys(&g, c),
        [
            "id",
            "type",
            "label",
            "cssClasses",
            "methods",
            "members",
            "annotations",
            "styles",
            "parent",
            "haveCallback",
            "tooltip",
            "link",
            "linkTarget"
        ]
    );
    let namespace = reference(&mapped(&g, reference(field(&g, r, "namespaces")), "A.B"));
    assert_eq!(
        reference(&mapped(&g, reference(field(&g, namespace, "classes")), "C")),
        c
    );
    let a = reference(&mapped(&g, reference(field(&g, r, "namespaces")), "A"));
    assert_eq!(
        keys(&g, a),
        ["id", "label", "classes", "notes", "children", "parent", "explicit"]
    );
    assert!(matches!(field(&g, a, "parent"), Atom::Undefined));
    assert_eq!(
        reference(&mapped(&g, reference(field(&g, a, "children")), "A.B")),
        namespace
    );
    assert!(matches!(g.nodes[a as usize], Node::Object { .. }));
    let note = reference(&mapped(&g, reference(field(&g, r, "notes")), "note0"));
    assert_eq!(
        reference(&mapped(
            &g,
            reference(field(&g, namespace, "notes")),
            "note0"
        )),
        note
    );
    for tag in ["default", "hot", "clickable"] {
        let set = reference(&mapped(&g, reference(field(&g, r, "withCssClass")), tag));
        let Node::Set { values, .. } = &g.nodes[set as usize] else {
            panic!()
        };
        assert_eq!(values.len(), 1);
        assert_eq!(reference(&values[0]), c);
    }
    let method = reference(&array(&g, reference(field(&g, c, "methods")))[0]);
    assert!(matches!(
        g.nodes[method as usize],
        Node::Instance {
            prototype: pele::compat::public::PrototypeId(2),
            ..
        }
    ));
    assert_eq!(
        keys(&g, method),
        [
            "id",
            "memberType",
            "visibility",
            "classifier",
            "parameters",
            "returnType"
        ]
    );
    same_source(&mut doc, source);
    // A replaced class in the root map doesn't repair the namespace or tag cache.
    let replacement = g.nodes.len() as u32;
    g.nodes.push(g.nodes[c as usize].clone());
    let styles = push_array(&mut g, vec![]);
    property(&mut g, replacement, "styles", Atom::Ref(styles));
    let classes = reference(field(&g, r, "classes"));
    let Node::Map { entries, .. } = &mut g.nodes[classes as usize] else {
        panic!()
    };
    entries[0].1 = Atom::Ref(replacement);
    doc.apply(doc.revision(), g).unwrap();
    assert!(invoke(&mut doc, "defineClass", |g| {
        let id = string(g, "hot");
        let ids = push_array(g, vec![id]);
        let style = string(g, "stroke:#123");
        let styles = push_array(g, vec![style]);
        vec![Atom::Ref(ids), Atom::Ref(styles)]
    })
    .result
    .is_ok());
    let g = doc.snapshot().unwrap();
    assert_eq!(
        texts_of(&g, reference(field(&g, c, "styles"))),
        ["stroke:#123"]
    );
    assert!(texts_of(&g, reference(field(&g, replacement, "styles"))).is_empty());
    // Empty link still appends an own undefined link before linkTarget.
    assert!(
        invoke(&mut doc, "setLink", |g| vec![string(g, "C"), string(g, "")])
            .result
            .is_ok()
    );
    let g = doc.snapshot().unwrap();
    assert!(matches!(field(&g, replacement, "link"), Atom::Undefined));
    assert!(g
        .text(field(&g, replacement, "linkTarget"))
        .unwrap()
        .is("_blank"));
    let mut standalone = parsed("classDiagram\nnote \"Standalone\"\nA");
    let g = standalone.snapshot().unwrap();
    let note = reference(&mapped(
        &g,
        reference(field(&g, root(&g), "notes")),
        "note0",
    ));
    assert_eq!(keys(&g, note), ["id", "class", "text", "index"]);
    assert!(matches!(field(&g, note, "class"), Atom::Undefined));
    same_source(&mut standalone, "classDiagram\nnote \"Standalone\"\nA");
}
#[test]
fn class_native_partial_errors_reversal_and_owned_alias_returns() {
    let mut doc = parsed(SOURCE);
    let mut g = doc.snapshot().unwrap();
    let r = root(&g);
    property(&mut g, r, "withCssClass", Atom::Null);
    doc.apply(doc.revision(), g).unwrap();
    let out = invoke(&mut doc, "addClass", |g| vec![string(g, "B~T~")]);
    is_type_error(&out, "Cannot read properties of null (reading 'get')");
    let b = class(&out.graph, "B");
    assert!(out
        .graph
        .text(field(&out.graph, b, "type"))
        .unwrap()
        .is("T"));
    let mut g = out.graph;
    let map = g.nodes.len() as u32;
    g.nodes.push(Node::Map {
        entries: vec![],
        properties: vec![],
    });
    property(&mut g, r, "withCssClass", Atom::Ref(map));
    doc.apply(doc.revision(), g).unwrap();
    let out = invoke(&mut doc, "ensure", |g| vec![string(g, "B")]);
    assert_eq!(reference(out.result.as_ref().unwrap()), b);
    let out = invoke(&mut doc, "setCssClass", |g| {
        vec![string(g, "B"), Atom::Number(7.)]
    });
    assert!(matches!(
        out.result,
        Err(PublicError::JavaScript {
            name: JavaScriptErrorKind::TypeError,
            ..
        })
    ));
    assert!(out
        .graph
        .text(field(&out.graph, b, "cssClasses"))
        .unwrap()
        .is("default 7"));
    // Caller relation is mutated in place before its later trim failure.
    let mut relation_id = 0;
    let out = invoke(&mut doc, "addRelation", |g| {
        let id1 = string(g, "C~U~");
        let id2 = string(g, "D~V~");
        let none = string(g, "none");
        let relation = push_object(
            g,
            vec![
                ("type1", none),
                ("type2", Atom::Number(3.)),
                ("lineType", Atom::Number(0.)),
            ],
        );
        let title = string(g, " none ");
        relation_id = push_object(
            g,
            vec![
                ("id1", id1),
                ("id2", id2),
                ("relation", Atom::Ref(relation)),
                ("relationTitle1", title),
                ("relationTitle2", Atom::Null),
            ],
        );
        vec![Atom::Ref(relation_id)]
    });
    is_type_error(&out, "Cannot read properties of null (reading 'trim')");
    assert!(out
        .graph
        .text(field(&out.graph, relation_id, "id1"))
        .unwrap()
        .is("C"));
    assert!(out
        .graph
        .text(field(&out.graph, relation_id, "id2"))
        .unwrap()
        .is("D"));
    assert!(out
        .graph
        .text(field(&out.graph, relation_id, "relationTitle1"))
        .unwrap()
        .is("none"));
    assert_eq!(
        array(&out.graph, reference(field(&out.graph, r, "relations"))).len(),
        0
    );
    // Native Array.reverse mutates the caller before invoking any addMember.
    let mut array_id = 0;
    let out = invoke(&mut doc, "addMembers", |g| {
        let a = string(g, "first");
        let b = string(g, "last");
        array_id = push_array(g, vec![a, b]);
        let a = class(g, "A");
        let members = reference(field(g, a, "members"));
        let key = string(g, "length");
        let Atom::String(key) = key else { panic!() };
        g.nodes[members as usize].properties_mut().push(Property {
            key,
            value: Atom::Number(0.),
            flags: 0,
        });
        vec![string(g, "A"), Atom::Ref(array_id)]
    });
    is_type_error(
        &out,
        "Cannot assign to read only property 'length' of object '[object Array]'",
    );
    assert_eq!(texts_of(&out.graph, array_id), ["last", "first"]);
    // Namespace stack publication happens before a bad namespaces Map is read.
    let mut g = out.graph;
    property(&mut g, r, "namespaces", Atom::Null);
    doc.apply(doc.revision(), g).unwrap();
    let out = invoke(&mut doc, "addNamespace", |g| vec![string(g, "Outer.Inner")]);
    is_type_error(&out, "Cannot read properties of null (reading 'get')");
    assert_eq!(
        texts_of(
            &out.graph,
            reference(field(&out.graph, r, "namespaceStack"))
        ),
        ["Outer.Inner"]
    );
}
#[test]
fn class_public_engine_complete_historical_corpus() {
    use serde_json::Value as J;
    struct Host<'a>(&'a J);
    impl RenderResources for Host<'_> {
        fn text_width(&mut self, r: TextRequest<'_>) -> Result<f64, PeleError> {
            if self.0["measure"] == "fixed" {
                Ok(r.text.encode_utf16().count() as f64
                    * r.size
                    * if r.style & 1 != 0 { 0.71 } else { 0.6 })
            } else {
                MetricsResources.text_width(r)
            }
        }
        fn icon(&mut self, name: &str) -> Result<Option<TrustedSvg>, PeleError> {
            Ok(self.0["icons"][name]
                .as_str()
                .map(|s| TrustedSvg::from_trusted_markup(s.into())))
        }
    }
    let fixture: J = serde_json::from_str(
        &std::fs::read_to_string(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../fixtures/pele/class.json"
        ))
        .unwrap(),
    )
    .unwrap();
    let cases = fixture["cases"].as_array().unwrap();
    let mut engine = PublicEngine::empty();
    engine.register(Class);
    let oracle: J = serde_json::from_str(ORACLE).unwrap();
    let exclusions = oracle["transportExclusions"].as_array().unwrap();
    assert_eq!(exclusions.len(), 2);
    let mut transport_checked = 0;
    let mut failures = vec![];
    for case in cases {
        let options: RenderOptions = serde_json::from_value(case["options"].clone()).unwrap();
        let expected = &case["expected"];
        if let Some(boundary) = exclusions.iter().find(|v| v["id"] == case["id"]) {
            assert_eq!(
                boundary["sourceSha256"],
                format!(
                    "{:x}",
                    Sha256::digest(case["source"].as_str().unwrap().as_bytes())
                )
            );
            assert_eq!(boundary["limits"]["publicGraphUtf16Units"], 16_000_000);
            assert_eq!(boundary["limits"]["upstreamOutputCharacters"], 4_000_000);
            assert_eq!(expected["error"], boundary["upstreamError"]);
            let error = engine
                .parse(case["source"].as_str().unwrap(), &options.parse)
                .err()
                .unwrap();
            assert_eq!(
                serde_json::to_value(error).unwrap(),
                boundary["nativeError"]
            );
            transport_checked += 1;
            continue;
        }
        let mut model = None;
        let actual = (|| -> Result<J, PeleError> {
            let mut doc = engine.parse(case["source"].as_str().unwrap(), &options.parse)?;
            if case["host"]["modelProjection"] != "excluded" {
                let graph = doc.snapshot()?;
                model = Some(project(&graph, &graph.root, false));
            }
            let rendered = doc.render(&options, &mut Host(&case["host"]))?;
            let mut result = serde_json::to_value(rendered).unwrap();
            if expected["result"].get("svgSha256").is_some() {
                let svg = result.as_object_mut().unwrap().remove("svg").unwrap();
                result["svgSha256"] =
                    format!("{:x}", Sha256::digest(svg.as_str().unwrap().as_bytes())).into();
            }
            Ok(if let Some(model) = &model {
                serde_json::json!({"model":model,"result":result})
            } else {
                serde_json::json!({"result":result})
            })
        })();
        let actual = match actual {
            Ok(v) => v,
            Err(error) => {
                if let Some(model) = model {
                    serde_json::json!({"model":model,"error":error})
                } else {
                    serde_json::json!({"error":error})
                }
            }
        };
        if actual != *expected {
            if failures.len() < 5 {
                eprintln!(
                    "class public {} model={} render={} actualError={} expectedError={}",
                    case["id"],
                    actual.get("model") == expected.get("model"),
                    actual.get("result") == expected.get("result"),
                    actual["error"],
                    expected["error"]
                )
            }
            failures.push(case["id"].clone());
        }
    }
    assert_eq!(transport_checked, 2);
    assert!(
        failures.is_empty(),
        "{} / {} mismatches: {:?}",
        failures.len(),
        cases.len(),
        failures.get(..failures.len().min(16)).unwrap()
    );
}
#[test]
fn class_borrowed_member_readonly_partial_state_and_reverse_descriptors() {
    let mut doc = parsed("classDiagram\nclass A {\n+run(a) bool*\n}");
    let mut g = doc.snapshot().unwrap();
    let r = root(&g);
    let a = class(&g, "A");
    let member = reference(&array(&g, reference(field(&g, a, "methods")))[0]);
    let proto_method = doc
        .model_schema()
        .methods
        .iter()
        .find(|m| m.name == "getDisplayDetails")
        .unwrap()
        .id;
    let borrowed = push_object(&mut g, vec![]);
    g.nodes[borrowed as usize] = Node::Object {
        properties: g.nodes[member as usize].properties().to_vec(),
    };
    property(
        &mut g,
        borrowed,
        "parseClassifier",
        Atom::BuiltinFunction(27),
    );
    doc.apply(doc.revision(), g).unwrap();
    let first = doc
        .invoke(
            doc.revision(),
            MethodCall {
                method: proto_method,
                receiver: Atom::Ref(borrowed),
                arguments: vec![],
            },
            &mut MetricsResources,
        )
        .unwrap();
    let result = reference(first.result.as_ref().unwrap());
    assert!(first
        .graph
        .text(field(&first.graph, result, "displayText"))
        .unwrap()
        .is("+run(a) : bool"));
    let next = doc
        .invoke(
            doc.revision(),
            MethodCall {
                method: proto_method,
                receiver: Atom::Ref(borrowed),
                arguments: vec![],
            },
            &mut MetricsResources,
        )
        .unwrap();
    assert_ne!(reference(next.result.as_ref().unwrap()), result);
    let mut g = next.graph;
    for p in g.nodes[member as usize].properties_mut() {
        if first.graph.strings[p.key as usize].is("parameters") {
            p.flags = 5;
        }
    }
    doc.apply(doc.revision(), g).unwrap();
    let args = apply_args(&mut doc, |g| vec![string(g, "#changed(new) NewType$")]);
    let id = doc
        .model_schema()
        .methods
        .iter()
        .find(|m| m.name == "parseMethod")
        .unwrap()
        .id;
    let out = doc
        .invoke(
            doc.revision(),
            MethodCall {
                method: id,
                receiver: Atom::Ref(member),
                arguments: args,
            },
            &mut MetricsResources,
        )
        .unwrap();
    assert!(matches!(
        out.result,
        Err(PublicError::JavaScript {
            name: JavaScriptErrorKind::TypeError,
            ..
        })
    ));
    assert!(out
        .graph
        .text(field(&out.graph, member, "id"))
        .unwrap()
        .is("changed"));
    assert!(out
        .graph
        .text(field(&out.graph, member, "visibility"))
        .unwrap()
        .is("#"));
    assert!(out
        .graph
        .text(field(&out.graph, member, "parameters"))
        .unwrap()
        .is("a"));
    assert!(out
        .graph
        .text(field(&out.graph, member, "returnType"))
        .unwrap()
        .is("bool"));
    // Receiver uses its actual helper identity; a borrowed plain object can opt
    // into the native ensure/addClass chain without acquiring a ClassDb prototype.
    let mut g = out.graph;
    let classes = field(&g, r, "classes").clone();
    let object = push_object(
        &mut g,
        vec![("classes", classes), ("ensure", Atom::BuiltinFunction(3))],
    );
    doc.apply(doc.revision(), g).unwrap();
    let args = apply_args(&mut doc, |g| {
        vec![string(g, "A"), string(g, "Borrowed label")]
    });
    let id = doc
        .model_schema()
        .methods
        .iter()
        .find(|m| m.name == "setClassLabel")
        .unwrap()
        .id;
    let out = doc
        .invoke(
            doc.revision(),
            MethodCall {
                method: id,
                receiver: Atom::Ref(object),
                arguments: args.clone(),
            },
            &mut MetricsResources,
        )
        .unwrap();
    is_type_error(&out, "this.addClass is not a function");
    let mut g = out.graph;
    property(&mut g, object, "addClass", Atom::BuiltinFunction(1));
    doc.apply(doc.revision(), g).unwrap();
    assert!(doc
        .invoke(
            doc.revision(),
            MethodCall {
                method: id,
                receiver: Atom::Ref(object),
                arguments: args
            },
            &mut MetricsResources
        )
        .unwrap()
        .result
        .is_ok());
    let mut g = doc.snapshot().unwrap();
    let one = string(&mut g, "first");
    let two = string(&mut g, "second");
    let members = push_array(&mut g, vec![one, two]);
    let key_ids = g.strings.clone();
    for p in g.nodes[members as usize].properties_mut() {
        if key_ids[p.key as usize].is("1") {
            p.flags = 5;
        }
    }
    doc.apply(doc.revision(), g).unwrap();
    let args = apply_args(&mut doc, |g| vec![string(g, "A"), Atom::Ref(members)]);
    let out = method(&mut doc, "addMembers", args);
    assert!(matches!(
        out.result,
        Err(PublicError::JavaScript {
            name: JavaScriptErrorKind::TypeError,
            ..
        })
    ));
    assert_eq!(texts_of(&out.graph, members), ["second", "second"]);
}
#[test]
fn class_retained_registration_deep_graph_output_and_resource_recovery() {
    let count = Arc::new(AtomicUsize::new(0));
    let mut engine = PublicEngine::empty();
    engine.register(Counted(count.clone()));
    let mut doc = engine.parse(SOURCE, &Default::default()).unwrap();
    engine.register(Class);
    drop(engine);
    assert!(invoke(&mut doc, "addMember", |g| vec![
        string(g, "A"),
        string(g, "+value int")
    ])
    .result
    .is_ok());
    same_source(&mut doc, "classDiagram\nclass A {\n+value int\n}");
    assert_eq!(count.load(Ordering::SeqCst), 1);
    let stable = serde_json::to_string(&doc.snapshot().unwrap()).unwrap();
    let mut options = RenderOptions::default();
    options.render.output_limit = Some(24);
    assert_eq!(
        doc.render(&options, &mut MetricsResources)
            .unwrap_err()
            .code,
        ErrorCode::Limit
    );
    assert_eq!(
        serde_json::to_string(&doc.snapshot().unwrap()).unwrap(),
        stable
    );
    struct Broken;
    impl RenderResources for Broken {
        fn text_width(&mut self, _: TextRequest<'_>) -> Result<f64, PeleError> {
            Err(PeleError::new(
                "class host metric failed",
                ErrorCode::Semantic,
            ))
        }
    }
    assert_eq!(
        doc.render(&Default::default(), &mut Broken)
            .unwrap_err()
            .message,
        "class host metric failed"
    );
    same_source(&mut doc, "classDiagram\nclass A {\n+value int\n}");
    let mut g = doc.snapshot().unwrap();
    let r = root(&g);
    let mut prior = r;
    for _ in 0..6000 {
        prior = push_object(&mut g, vec![("next", Atom::Ref(prior))]);
    }
    let raw = g.strings.len() as u32;
    g.strings.push(JsString(vec![0xd800, 97, 0xdc00]));
    property(&mut g, prior, "raw", Atom::String(raw));
    property(
        &mut g,
        prior,
        "nan",
        Atom::Number(f64::from_bits(0x7ff8_0000_0000_0042)),
    );
    property(&mut g, r, "deep", Atom::Ref(prior));
    let json = serde_json::to_string(&g).unwrap();
    let graph: ModelGraph = serde_json::from_str(&json).unwrap();
    doc.apply(doc.revision(), graph).unwrap();
    assert_eq!(
        serde_json::to_string(&doc.snapshot().unwrap()).unwrap(),
        json
    );
    same_source(&mut doc, "classDiagram\nclass A {\n+value int\n}");
    let method_id = doc.model_schema().methods[0].id;
    let revision = doc.revision();
    assert!(doc
        .invoke(
            revision,
            MethodCall {
                method: method_id,
                receiver: Atom::Ref(r),
                arguments: vec![Atom::Ref(u32::MAX)]
            },
            &mut MetricsResources
        )
        .is_err());
    assert_eq!(doc.revision(), revision);
    let args = apply_args(&mut doc, |g| vec![string(g, "B")]);
    assert!(doc
        .invoke(
            revision,
            MethodCall {
                method: method_id,
                receiver: Atom::Ref(r),
                arguments: args
            },
            &mut MetricsResources
        )
        .is_err());
    assert_eq!(count.load(Ordering::SeqCst), 1);
    let mut g = doc.snapshot().unwrap();
    delete(&mut g, r, "deep");
    doc.apply(doc.revision(), g).unwrap();
    assert_eq!(doc.diagram_type().as_str(), "class");
    // Additive numeric IR marker variants preserve exact comparisons as well.
    assert!(RelationEnd::RawNumber(4.).is(4));
    assert!(!RelationEnd::RawNumber(f64::NAN).is(4));
}
#[test]
fn class_live_alias_iteration_import_expansion_and_unused_fields() {
    let mut doc = parsed("classDiagram\nclass A {\n+value int\n}");
    let mut g = doc.snapshot().unwrap();
    let r = root(&g);
    let a = class(&g, "A");
    let member = reference(&array(&g, reference(field(&g, a, "members")))[0]);
    let cycle = push_object(&mut g, vec![]);
    property(&mut g, cycle, "self", Atom::Ref(cycle));
    property(&mut g, member, "parameters", Atom::Ref(cycle));
    property(&mut g, member, "returnType", Atom::Ref(cycle));
    let classifier = g.strings.len() as u32;
    g.strings.push(JsString(vec![0xd800]));
    property(&mut g, member, "classifier", Atom::String(classifier));
    doc.apply(doc.revision(), g).unwrap();
    same_source(&mut doc, "classDiagram\nclass A {\n+value int\n}");
    // setCssStyle iterates its actual Array, which can be its own destination.
    let mut g = doc.snapshot().unwrap();
    let styles = reference(field(&g, a, "styles"));
    let style = string(&mut g, "fill:#abc");
    property(&mut g, styles, "0", style);
    if let Node::Array { length, .. } = &mut g.nodes[styles as usize] {
        *length = 1
    }
    doc.apply(doc.revision(), g).unwrap();
    let args = apply_args(&mut doc, |g| vec![string(g, "A"), Atom::Ref(styles)]);
    let out = method(&mut doc, "setCssStyle", args);
    assert!(matches!(
        out.result,
        Err(PublicError::Pele(PeleError {
            code: ErrorCode::Limit,
            ..
        }))
    ));
    assert!(array(&out.graph, styles).len() > 1);
    let mut g = out.graph;
    let empty = push_array(&mut g, vec![]);
    property(&mut g, a, "styles", Atom::Ref(empty));
    doc.apply(doc.revision(), g).unwrap();
    same_source(&mut doc, "classDiagram\nclass A {\n+value int\n}");
    // Repeated aliases are bounded before expansion into concrete member strings.
    let mut g = doc.snapshot().unwrap();
    let long = string(&mut g, &"x".repeat(65536));
    property(&mut g, member, "id", long);
    let repeated = push_array(&mut g, vec![Atom::Ref(member); 1024]);
    property(&mut g, a, "members", Atom::Ref(repeated));
    doc.apply(doc.revision(), g).unwrap();
    assert_eq!(
        doc.render(&Default::default(), &mut MetricsResources)
            .unwrap_err()
            .code,
        ErrorCode::Limit
    );
    let mut g = doc.snapshot().unwrap();
    let empty = push_array(&mut g, vec![]);
    property(&mut g, a, "members", Atom::Ref(empty));
    doc.apply(doc.revision(), g).unwrap();
    same_source(&mut doc, SOURCE);
    // A compact class definition also expands per drawn class. Preserve the graph
    // and reject excessive concrete compilation before geometry allocation.
    let mut g = doc.snapshot().unwrap();
    let class_name = string(&mut g, "big");
    let style = string(&mut g, &format!("fill:{}", "x".repeat(65536)));
    let styles = push_array(&mut g, vec![style]);
    let text_styles = push_array(&mut g, vec![]);
    let def = push_object(
        &mut g,
        vec![
            ("id", class_name.clone()),
            ("styles", Atom::Ref(styles)),
            ("textStyles", Atom::Ref(text_styles)),
        ],
    );
    let defs = reference(field(&g, r, "styleClasses"));
    let Node::Map { entries, .. } = &mut g.nodes[defs as usize] else {
        panic!()
    };
    entries.push((class_name, Atom::Ref(def)));
    let css = string(&mut g, "default big");
    property(&mut g, a, "cssClasses", css);
    let classes = reference(field(&g, r, "classes"));
    for n in 0..2048 {
        let key = string(&mut g, &format!("Alias{n}"));
        let Node::Map { entries, .. } = &mut g.nodes[classes as usize] else {
            panic!()
        };
        entries.push((key, Atom::Ref(a)));
    }
    doc.apply(doc.revision(), g).unwrap();
    assert_eq!(
        doc.render(&Default::default(), &mut MetricsResources)
            .unwrap_err()
            .code,
        ErrorCode::Limit
    );
    let mut g = doc.snapshot().unwrap();
    let Node::Map { entries, .. } = &mut g.nodes[classes as usize] else {
        panic!()
    };
    entries.truncate(1);
    let default = string(&mut g, "default");
    property(&mut g, a, "cssClasses", default);
    doc.apply(doc.revision(), g).unwrap();
    same_source(&mut doc, SOURCE);
}
#[test]
fn class_native_builder_forty_thousand_pinned_member_inputs() {
    let oracle: serde_json::Value = serde_json::from_str(ORACLE).unwrap();
    let campaign = &oracle["campaign"];
    let pieces = campaign["pieces"].as_array().unwrap();
    let mut state = campaign["seed"].as_u64().unwrap() as u32;
    let mut random = || {
        state = state.wrapping_mul(1664525).wrapping_add(1013904223);
        f64::from(state) / 4294967296.
    };
    let digest = |value: &serde_json::Value| {
        format!("{:x}", Sha256::digest(serde_json::to_vec(value).unwrap()))
    };
    for (index, expected) in campaign["cases"].as_array().unwrap().iter().enumerate() {
        let mut input = vec![];
        for _ in 0..campaign["groupSize"].as_u64().unwrap() {
            let count = 1 + (random() * campaign["maxPieces"].as_f64().unwrap()).floor() as usize;
            let mut s = String::new();
            for _ in 0..count {
                s.push_str(
                    pieces[(random() * pieces.len() as f64).floor() as usize]
                        .as_str()
                        .unwrap(),
                );
            }
            input.push(s);
        }
        let input = serde_json::to_value(input).unwrap();
        assert_eq!(
            digest(&input),
            expected["inputsSha256"],
            "group{index} inputs"
        );
        let mut doc = parsed(SOURCE);
        let args = apply_args(&mut doc, |g| vec![string(g, "A"), argument(g, &input)]);
        let out = method(&mut doc, "addMembers", args);
        assert!(out.result.is_ok(), "group{index} {:?}", out.result);
        assert_eq!(
            digest(&project(&out.graph, &out.graph.root, true)),
            expected["modelSha256"],
            "group{index} complete model"
        );
        let a = class(&out.graph, "A");
        let methods = array(&out.graph, reference(field(&out.graph, a, "methods")));
        let members = array(&out.graph, reference(field(&out.graph, a, "members")));
        let receiver = methods.first().or_else(|| members.first()).unwrap().clone();
        let id = doc
            .model_schema()
            .methods
            .iter()
            .find(|m| m.name == "getDisplayDetails")
            .unwrap()
            .id;
        let out = doc
            .invoke(
                doc.revision(),
                MethodCall {
                    method: id,
                    receiver,
                    arguments: vec![],
                },
                &mut MetricsResources,
            )
            .unwrap();
        let result = out.result.unwrap();
        assert_eq!(
            project(&out.graph, &result, true),
            expected["details"],
            "group{index} nested prototype display"
        );
        let rendered = svg(&mut doc);
        assert_eq!(
            format!("{:x}", Sha256::digest(rendered.svg.as_bytes())),
            expected["svgSha256"],
            "group{index} complete SVG"
        );
        assert_eq!(
            (rendered.width, rendered.height),
            (
                expected["width"].as_f64().unwrap(),
                expected["height"].as_f64().unwrap()
            )
        );
    }
    assert_eq!(
        campaign["cases"].as_array().unwrap().len()
            * campaign["groupSize"].as_u64().unwrap() as usize,
        40000
    );
}
